// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }

    // owner of c is address(this); accept the withdrawn funds
    receive() external payable {}

    function testFuzz_property(uint256 amount, address depositor) public {
        // admissible domain: a real, distinct depositor, positive amount, funded
        vm.assume(depositor != address(0));
        vm.assume(depositor != address(this));
        vm.assume(depositor.code.length == 0);
        amount = bound(amount, 1, type(uint256).max / 2);
        vm.assume(address(this).balance <= type(uint256).max - amount);

        // depositor funds the contract through its payable fallback
        vm.deal(depositor, amount);
        vm.prank(depositor);
        (bool okDep, ) = address(c).call{value: amount}("");
        assertTrue(okDep);
        assertTrue(address(c).balance == amount);
        assertTrue(c.depositsCount() == 1);

        // owner (deployer, address(this)) withdraws everything
        uint256 ownerBefore = address(this).balance;
        c.withdrawAll();

        // RULE: the deposited funds actually moved out of c to the owner
        assertTrue(
            address(c).balance == 0 && address(this).balance == ownerBefore + amount
        );
    }
}
